// Release 1.0 anti-cheat: export a coarse wall map (0.5 m voxels of the walls, floors left out) for every map, so
// the server can check that a hit had a line of sight. Run it against a running build of the game:
//   node tools/los-export.mjs http://127.0.0.1:8080/ server/los-maps.json
// (needs Playwright and a Chromium; the game's maps are generated by the game itself, so the walls come from it)
import { chromium } from 'playwright';
import zlib from 'node:zlib';
import fs from 'node:fs';
const url = process.argv[2] || 'http://127.0.0.1:8080/', out = process.argv[3] || 'server/los-maps.json';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const browser = await chromium.launch({ executablePath: process.env.CHROMIUM || undefined, args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--js-flags=--max-old-space-size=6144'] });
const page = await browser.newPage({ viewport: { width: 800, height: 450 } });
page.on('pageerror', (e) => console.log('PAGEERR', String(e.stack || e).slice(0, 300)));
await page.addInitScript(() => { try { localStorage.setItem('vangaurd.auth.offline', '1'); localStorage.setItem('vangaurd.news.off', '1'); localStorage.setItem('vangaurd.halloween', 'off'); } catch {} });
await page.goto(url, { timeout: 900000 });
await page.waitForFunction(() => !!window.__GAME__ && ['main', 'entry'].includes(window.__GAME__.ctx.services.hud.menu) && !document.querySelector('.vg-boot.on'), null, { timeout: 900000, polling: 500 });
await page.evaluate(() => { const g = window.__GAME__; g.ctx.services.postfx.render = () => {}; g.engine.renderer.render = () => {}; });
const maps = await page.evaluate(() => window.__GAME__.ctx.services.world.maps().map((m) => m.id));
console.log('maps', maps.join(', '));
const result = {};
for (const id of maps) {
  const t0 = Date.now();
  const ok = await page.evaluate(async (id) => { try { await window.__GAME__.ctx.services.world.loadMap(id); return window.__GAME__.ctx.services.world.mapId; } catch (e) { return 'ERR ' + e.message; } }, id);
  if (ok !== id) { console.log('skip', id, ok); continue; }
  await sleep(500);
  const v = await page.evaluate(() => {
    const W = window.__GAME__.ctx.services.world, B = W.bounds, res = 0.5;
    const min = [Math.floor(B.min.x - 4), Math.floor((Number.isFinite(B.min.y) ? B.min.y : 0) - 2), Math.floor(B.min.z - 4)], max = [Math.ceil(B.max.x + 4), 0, Math.ceil(B.max.z + 4)];
    max[1] = min[1] + 32;
    const nx = Math.ceil((max[0] - min[0]) / res), ny = Math.ceil((max[1] - min[1]) / res), nz = Math.ceil((max[2] - min[2]) / res);
    const bits = new Uint8Array(Math.ceil(nx * ny * nz / 8));
    let tris = 0, marked = 0;
    const mark = (x, y, z) => {
      const i = Math.floor((x - min[0]) / res), j = Math.floor((y - min[1]) / res), k = Math.floor((z - min[2]) / res);
      if (i < 0 || j < 0 || k < 0 || i >= nx || j >= ny || k >= nz) return;
      const n = (j * nz + k) * nx + i;
      bits[n >> 3] & 1 << (n & 7) || (bits[n >> 3] |= 1 << (n & 7), marked++);
    };
    const V = (window.__GAME__.ctx.camera.position.constructor), a = new V(), b = new V(), c = new V(), e1 = new V(), e2 = new V(), nn = new V(), p = new V();
    for (const m of W.colliders) {
      const g = m.geometry, pos = g?.attributes?.position;
      if (!pos) continue;
      m.updateMatrixWorld(!0);
      const idx = g.index, count = idx ? idx.count : pos.count;
      for (let t = 0; t + 2 < count; t += 3) {
        const i0 = idx ? idx.getX(t) : t, i1 = idx ? idx.getX(t + 1) : t + 1, i2 = idx ? idx.getX(t + 2) : t + 2;
        a.fromBufferAttribute(pos, i0).applyMatrix4(m.matrixWorld), b.fromBufferAttribute(pos, i1).applyMatrix4(m.matrixWorld), c.fromBufferAttribute(pos, i2).applyMatrix4(m.matrixWorld);
        e1.subVectors(b, a), e2.subVectors(c, a), nn.crossVectors(e1, e2);
        const area = nn.length();
        if (area < 1e-6) continue;
        nn.multiplyScalar(1 / area);
        // floors, roofs and the ground are left out: only walls and other upright surfaces block a shot here
        if (Math.abs(nn.y) > 0.8) continue;
        tris++;
        const L = Math.max(a.distanceTo(b), b.distanceTo(c), c.distanceTo(a)), n = Math.max(1, Math.ceil(L / (res * 0.45)));
        for (let u = 0; u <= n; u++) for (let w = 0; w <= n - u; w++) p.copy(a).addScaledVector(e1, u / n).addScaledVector(e2, w / n), mark(p.x, p.y, p.z);
      }
    }
    let s = '';
    for (let i = 0; i < bits.length; i += 8192) s += String.fromCharCode.apply(null, bits.subarray(i, i + 8192));
    return { min, res, dims: [nx, ny, nz], tris, marked, b64: btoa(s), colliders: W.colliders.length };
  });
  const raw = Buffer.from(v.b64, 'base64'), gz = zlib.gzipSync(raw, { level: 9 });
  result[id] = { min: v.min, res: v.res, dims: v.dims, bits: gz.toString('base64') };
  console.log(id, `colliders ${v.colliders} · walls ${v.tris} triangles · ${v.marked} solid of ${v.dims.join('x')} · ${(gz.length / 1024).toFixed(1)} KB · ${((Date.now() - t0) / 1000).toFixed(1)} s`);
}
fs.writeFileSync(out, JSON.stringify({ v: 1, note: 'Wall voxels per map for the server line-of-sight check. Made by tools/los-export.mjs.', maps: result }));
console.log('wrote', out, (fs.statSync(out).size / 1024).toFixed(1), 'KB');
await browser.close();
